import{z as o,x as l,o as e,c as n,q as A,j as s,D as a,d as t,s as i,S as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"优化器的调试与收束","description":"","frontmatter":{"title":"优化器的调试与收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cg-debugging-map.md","filePath":"cs/cg-debugging-map.md","lastUpdated":1791063341000}'),c={name:"cs/cg-debugging-map.md"};function p(d,E,C,h,D,m){const B=l("Mermaid");return e(),n("div",null,[E[2]||(E[2]=A('<h1 id="优化器的调试与收束" tabindex="-1">优化器的调试与收束 <a class="header-anchor" href="#优化器的调试与收束" aria-label="Permalink to &quot;优化器的调试与收束&quot;">​</a></h1><div class="epigraph"><p>编译器的 bug 与别处不同：它不坏在一个功能上，而坏在一条翻译上——你证明不了它对，就只能逼它在最小的例子里错给你看。</p><footer>—— 据 Yang et al., PLDI, 2011；Necula, PLDI, 2000 整理</footer></div><p><a href="/cs/cg-mlir-intuition">上一课</a>把多层 IR 的翻译装进同一个框架，本课程到此收束。收束课做两件事：给整条优化管线一份调试协议——从「好像不对」走到「某个 pass 的某次改写」；再把八课收成一张能带走的清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>优化器的病分两类，诊断路径完全不同。错译（miscompile）：源程序语义被改了——结果错、崩溃、断言炸；难在「语义等价」没有运行时表针，错误往往在离案发几千个 pass 之外显形。漏优化（missed optimization）：程序没错但慢了；难在「机会丢在哪一步」没有天然的观测点。共同敌人是相位顺序：每个 pass 都按自己看到的 IR 做局部正确的决定，组合起来互相挡路——<a href="/cs/peephole">窥孔</a>能收的残差、分配逼出的溢出、成本模型的错判，都长得像「编译器坏了」。还有一类假病：源代码踩了 UB，优化把 UB 推导成出人意料的行为——那不是 bug，<a href="/cs/compcert-correctness">CompCert 的边界</a>讲过：UB 不在正确性定理内。</p><p><span class="marginnote">常见误区：初学者遇到「加了 -O2 就出错」多半先骂编译器，实际上最常见的病因是源代码踩了未定义行为——比如有符号整数溢出或越界读。优化器只是把 UB 的后果沿着它敢做的变换推到了离案发很远的地方，正确性定理从来没担保过 UB 程序。</span></p><h3 id="从报告到案发现场" tabindex="-1">从报告到案发现场 <a class="header-anchor" href="#从报告到案发现场" aria-label="Permalink to &quot;从报告到案发现场&quot;">​</a></h3><p>协议四步。复现：固定编译器版本与命令行，钉死目标与优化级别。化简：用 C-Reduce 这类化简器把上万行的输入缩到几十行，前提是守住一个性质谓词（还错译、还崩溃）——化简的本质是在保持病灶的前提下删代码。二分：在 pass 序列上定位第一个让 IR 语义改变的 pass——<code>-print-after-all</code> 逐段看，<code>-start-after</code> 与 <code>-stop-after</code> 缩小窗口；IR verifier 只查结构良构，语义等价要靠翻译验证工具或人工对照。回归：化简后的用例进测试集，这是最便宜的回归资产。</p><p><span class="marginnote">术语翻译：性质谓词就是一段「病情仍在」的自动判定脚本——比如「编译产物跑完仍然崩溃」或「输出仍然含错误答案」。化简器每删一块代码前都跑一遍它，返回真才敢删；没有它，删着删着病灶就被删没了，缩出来的小用例反而不复现。</span></p><p><span class="marginnote">Csmith 的论文报了 325 个先前未知的 GCC/LLVM bug；随机程序动辄上万行，没有化简器就没有人读报告。差分测试回答「哪里错」，化简器把「哪里错」缩成「哪三行错」——两件工具是配套的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>漏优化的诊断靠「期待与实际的差」：先写下这一层 IR 应该长什么样——循环该融合、访存该合并、该走 <a href="/cs/cg-simd-autovec">SIMD</a>——再用 pass 之间的 diff 找机会在哪一步消失。常见案由有三：别名太保守，<a href="/cs/alias-analysis">别名分析</a>给不出证明，版本化也没开；成本模型判负，收益估小了，向量化或内联沉默放弃；相位挡路，前一个 pass 把模式弄散了，后一个 pass 认不出来。三者的修法是同一句：让信息活到用它的那一刻。</p>',12)),(e(),s(r,null,{default:a(()=>[i(B,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20REP%5B%22%E6%8A%A5%E5%91%8A%EF%BC%9A%E9%94%99%E8%AF%91%E6%88%96%E6%BC%8F%E4%BC%98%E5%8C%96%22%5D%20--%3E%20REPRO%5B%22%E5%A4%8D%E7%8E%B0%EF%BC%9A%E9%92%89%E7%89%88%E6%9C%AC%E4%B8%8E%E5%91%BD%E4%BB%A4%E8%A1%8C%22%5D%0A%20%20REPRO%20--%3E%20RED%5B%22%E5%8C%96%E7%AE%80%EF%BC%9A%E4%BF%9D%E6%80%A7%E8%B4%A8%E8%B0%93%E8%AF%8D%E5%88%A0%E4%BB%A3%E7%A0%81%22%5D%0A%20%20RED%20--%3E%20BIS%7B%22%E4%BA%8C%E5%88%86%20pass%20%E5%BA%8F%E5%88%97%22%7D%0A%20%20BIS%20--%3E%7C%E9%94%99%E8%AF%91%7C%20SEM%5B%22%E8%AF%AD%E4%B9%89%E7%AD%89%E4%BB%B7%E5%88%A4%E5%AE%9A%EF%BC%9A%E7%BF%BB%E8%AF%91%E9%AA%8C%E8%AF%81%20%2F%20%E4%BA%BA%E5%B7%A5%22%5D%0A%20%20BIS%20--%3E%7C%E6%BC%8F%E4%BC%98%E5%8C%96%7C%20DIFF%5B%22diff%20%E6%89%BE%E6%9C%BA%E4%BC%9A%E6%B6%88%E5%A4%B1%E7%82%B9%22%5D%0A%20%20SEM%20--%3E%20FIX%5B%22%E4%BF%AE%E5%A4%8D%20%2B%20%E5%9B%9E%E5%BD%92%E7%94%A8%E4%BE%8B%22%5D%0A%20%20DIFF%20--%3E%20FIX%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>八课收成一句：每一层都在「信息丢掉之前」做决定。<a href="/cs/cg-register-allocation-deep">分配</a>在物理寄存器定名之前算代价表；<a href="/cs/cg-instruction-selection">选择</a>在中端结构还在时做覆盖；<a href="/cs/cg-instruction-scheduling">调度</a>在依赖图还是纯真依赖时抢自由度；<a href="/cs/cg-simd-autovec">向量化</a>在标量代码还看得见循环时打包；<a href="/cs/cg-linker-deep">链接</a>在地址定下的最后一刻做回收、折叠与松弛；<a href="/cs/cg-jit-deep">JIT</a>把这一切搬进运行时，用守卫与去优化为「信息可能错」兜底；<a href="/cs/cg-mlir-intuition">MLIR</a>把「层级」本身变成可编程的，让结构晚一点丢。调试协议是这句总纲的逆用：错了，先找信息在哪一步丢的。</p>',2)),(e(),s(r,null,{default:a(()=>[i(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E7%A0%81%EF%BC%9A%E5%BE%AA%E7%8E%AF%E4%B8%8E%E7%B1%BB%E5%9E%8B%E7%BB%93%E6%9E%84%22%5D%20--%3E%20MID%5B%22%E4%B8%AD%E7%AB%AF%EF%BC%9A%E8%B7%A8%E8%BF%87%E7%A8%8B%E4%BF%A1%E6%81%AF%22%5D%0A%20%20MID%20--%3E%20LEP%5B%22%E9%80%89%E6%8B%A9%EF%BC%9A%E4%B8%AD%E7%AB%AF%E7%BB%93%E6%9E%84%E6%94%B9%E5%86%99%E4%B8%BA%E6%9C%BA%E5%99%A8%E8%AF%8D%E6%B1%87%22%5D%0A%20%20LEP%20--%3E%20RA%5B%22%E5%88%86%E9%85%8D%EF%BC%9A%E8%99%9A%E6%8B%9F%E5%90%8D%E6%8D%A2%E6%88%90%E7%89%A9%E7%90%86%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20RA%20--%3E%20SCH%5B%22%E8%B0%83%E5%BA%A6%EF%BC%9A%E8%87%AA%E7%94%B1%E5%BA%A6%E8%A2%AB%E9%A1%BA%E5%BA%8F%E5%9B%BA%E5%AE%9A%22%5D%0A%20%20SCH%20--%3E%20OBJ%5B%22%E7%9B%AE%E6%A0%87%E6%96%87%E4%BB%B6%EF%BC%9A%E5%9C%B0%E5%9D%80%E6%9C%AA%E5%AE%9A%22%5D%0A%20%20OBJ%20--%3E%20LNK%5B%22%E9%93%BE%E6%8E%A5%EF%BC%9A%E5%9C%B0%E5%9D%80%E5%AE%9A%E4%B8%8B%22%5D%0A%20%20LNK%20--%3E%20Q%7B%22%E5%93%AA%E4%B8%80%E7%BA%A7%E5%BC%80%E5%A7%8B%E9%94%99%EF%BC%9F%E5%9B%9E%E6%9F%A5%E8%AF%A5%E7%BA%A7%E5%BD%93%E6%97%B6%E8%BF%98%E5%89%A9%E4%BB%80%E4%B9%88%E4%BF%A1%E6%81%AF%22%7D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程不覆盖前端——解析与类型检查各有先修课——也不进入形式化验证的深处，CompCert 一课给过入口，全程序的翻译验证仍是开放问题。硬件自己的优化（乱序、预取、宏融合）在编译器可见性之外影响性能：调度器给过延迟表，表之外的事不归编译器管。附录——论文、引擎版本、ISA 手册——不插进主干，按各课随课标注取用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>病分两类：错译找第一个改坏语义的 pass，漏优化找机会消失的那一步。</li><li>化简保性质谓词，二分靠 pass 级 diff，语义判定靠翻译验证或人工。</li><li>相位顺序是共同敌人，UB 是最常见的假病。</li><li>八课一句总纲：每一层都在信息丢掉之前做决定。</li><li>出处：Yang et al., 2011（Csmith）；Regehr et al., 2012（C-Reduce）；Necula, 2000；Lopes et al., 2015（Alive）；Leroy, 2009（CompCert）。</li></ul>',4))])}const u=o(c,[["render",p]]);export{f as __pageData,u as default};
